def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of xs without modifying it."""
    ordered = sorted(xs)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return avg(ordered[middle - 1:middle + 1])

